package com.javacourse.config;

import org.springframework.boot.ApplicationArguments;
import org.springframework.boot.ApplicationRunner;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;

/** Idempotent additions for existing local/hosted databases. */
@Component
public class CourseFeatureSchemaUpgrade implements ApplicationRunner {
    private final JdbcTemplate jdbc;
    public CourseFeatureSchemaUpgrade(JdbcTemplate jdbc) { this.jdbc=jdbc; }

    @Override public void run(ApplicationArguments args) throws Exception {
        String textType;
        try(var c=jdbc.getDataSource().getConnection()) {
            String product=c.getMetaData().getDatabaseProductName().toLowerCase();
            textType=product.contains("kingbase")?"CLOB":"TEXT";
        }
        jdbc.execute("CREATE TABLE IF NOT EXISTS generated_course (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, owner_id BIGINT NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, title VARCHAR(160) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'DRAFT', source_name VARCHAR(255), source_url VARCHAR(1000), source_text "+textType+", course_json "+textType+" NOT NULL, share_token VARCHAR(64), share_revoked SMALLINT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP)");
        jdbc.execute("CREATE INDEX IF NOT EXISTS idx_generated_owner ON generated_course(owner_id,updated_at)");
        jdbc.execute("CREATE UNIQUE INDEX IF NOT EXISTS uk_generated_share ON generated_course(share_token)");
        jdbc.execute("CREATE TABLE IF NOT EXISTS learning_activity (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, lesson_id BIGINT NOT NULL REFERENCES lesson(id) ON DELETE CASCADE, session_key VARCHAR(64) NOT NULL, activity_date DATE NOT NULL DEFAULT CURRENT_DATE, session_seconds INTEGER NOT NULL DEFAULT 0, total_seconds INTEGER NOT NULL DEFAULT 0, completed SMALLINT NOT NULL DEFAULT 0, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP)");
        jdbc.execute("CREATE UNIQUE INDEX IF NOT EXISTS uk_activity_session_day ON learning_activity(user_id,lesson_id,session_key,activity_date)");
        jdbc.execute("CREATE INDEX IF NOT EXISTS idx_activity_user_day ON learning_activity(user_id,activity_date)");
        jdbc.execute("CREATE TABLE IF NOT EXISTS learning_session (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, lesson_id BIGINT NOT NULL REFERENCES lesson(id) ON DELETE CASCADE, session_key VARCHAR(64) NOT NULL, last_seconds INTEGER NOT NULL DEFAULT 0, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP)");
        jdbc.execute("CREATE UNIQUE INDEX IF NOT EXISTS uk_learning_session_key ON learning_session(user_id,lesson_id,session_key)");
        jdbc.execute("CREATE TABLE IF NOT EXISTS user_ai_config (user_id BIGINT PRIMARY KEY REFERENCES app_user(id) ON DELETE CASCADE, base_url VARCHAR(1000) NOT NULL, model VARCHAR(160) NOT NULL, encrypted_key VARCHAR(4096) NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP)");
    }
}

